const j = $input.first().json;
const body = (j && j.body) ? j.body : (j || {});
const organization = body.organization || '';
const repository = body.repository || '';
const branch = body.branch || '';
const commitSha = body.commitSha || '';
const pullRequestNumber = (body.pullRequestNumber === undefined) ? null : body.pullRequestNumber;
const missingFields = [];
if (!organization) missingFields.push('organization');
if (!repository) missingFields.push('repository');
if (!branch) missingFields.push('branch');
if (!commitSha) missingFields.push('commitSha');
const valid = missingFields.length === 0;
return [{ json: { valid, missingFields, organization, repository, branch, commitSha, pullRequestNumber } }];

const rows = $input.all().map(i => i.json).filter(r => r && r.cache_key);
const v = $('Validate Input').first().json;
let cacheHit = false;
let cachedMetadata = null;
let defaultBranch = '';
if (rows.length > 0) {
  const row = rows[0];
  const cachedAt = row.cached_at ? new Date(row.cached_at).getTime() : 0;
  const ageMs = Date.now() - cachedAt;
  if (cachedAt > 0 && ageMs < 24 * 60 * 60 * 1000) {
    cacheHit = true;
    cachedMetadata = row.metadata_json || null;
    defaultBranch = row.default_branch || '';
  }
}
return [{ json: {
  cacheHit, cachedMetadata, defaultBranch,
  cacheKey: (v.organization || '') + '/' + (v.repository || ''),
  organization: v.organization, repository: v.repository, branch: v.branch,
  commitSha: v.commitSha, pullRequestNumber: v.pullRequestNumber
} }];

const inItems = $input.all().map(i => i.json);
const commit = inItems[0] || {};
const v = $('Validate Input').first().json;
const files = Array.isArray(commit.files) ? commit.files : [];
const ignoreExt = ['.png','.jpg','.jpeg','.gif','.svg','.ico','.webp','.bmp','.pdf','.zip','.exe','.dll','.woff','.woff2','.ttf','.eot','.mp4','.mov','.gz','.tar'];
const ignoreNames = ['package-lock.json','yarn.lock','pnpm-lock.yaml','gemfile.lock','composer.lock','poetry.lock','cargo.lock'];
const ignoreDirs = ['node_modules/','dist/','build/','vendor/','bin/','obj/','.next/','out/','.git/'];
const ignorePatterns = ['.min.js','.min.css','.g.cs','.designer.cs','.generated.','.snap'];
const kept = [];
for (const f of files) {
  const name = (f.filename || '').toLowerCase();
  if (!name) continue;
  if (!f.patch) continue;
  let skip = false;
  for (const e of ignoreExt) { if (name.endsWith(e)) { skip = true; break; } }
  if (!skip) { const bn = name.split('/').pop(); for (const n of ignoreNames) { if (bn === n) { skip = true; break; } } }
  if (!skip) { for (const d of ignoreDirs) { if (name.indexOf(d) !== -1) { skip = true; break; } } }
  if (!skip) { for (const p of ignorePatterns) { if (name.indexOf(p) !== -1) { skip = true; break; } } }
  if (skip) continue;
  kept.push({ filename: f.filename, status: f.status, additions: f.additions || 0, deletions: f.deletions || 0, patch: f.patch });
}
const author = (commit.commit && commit.commit.author) ? commit.commit.author.name : '';
const message = (commit.commit && commit.commit.message) ? commit.commit.message : '';
const sha = commit.sha || v.commitSha;
return [{ json: {
  repository: v.repository, organization: v.organization, branch: v.branch,
  commitSha: v.commitSha, pullRequestNumber: v.pullRequestNumber,
  author, message, sha, keptFiles: kept, hasFiles: kept.length > 0
} }];

const d = $input.first().json;
const files = Array.isArray(d.keptFiles) ? d.keptFiles.slice() : [];
files.sort((a, b) => ((b.additions || 0) + (b.deletions || 0)) - ((a.additions || 0) + (a.deletions || 0)));
const CAP = 12000;
const NL = String.fromCharCode(10);
let ctx = '';
let truncated = false;
for (const f of files) {
  const header = 'FILE: ' + f.filename + ' (' + f.status + ', +' + (f.additions || 0) + '/-' + (f.deletions || 0) + ')';
  const block = header + NL + (f.patch || '') + NL + NL;
  if (ctx.length + block.length > CAP) {
    const remaining = CAP - ctx.length;
    if (remaining > 200) { ctx += block.substring(0, remaining) + NL + '...[truncated]'; }
    truncated = true;
    break;
  }
  ctx += block;
}
return [{ json: {
  codeContext: ctx, hasFiles: (d.hasFiles && ctx.length > 0), truncated,
  repository: d.repository, organization: d.organization, branch: d.branch,
  commitSha: d.commitSha, pullRequestNumber: d.pullRequestNumber,
  author: d.author, message: d.message
} }];

const ctx = $input.first().json;
const codeContext = ctx.codeContext || '';
const repository = ctx.repository || '';
const commitSha = ctx.commitSha || '';
const base = ' Analyze ONLY the provided diff. Respond with a JSON object containing: score (integer 0-100), issues (array of objects with title, severity one of critical|high|medium|low, detail, recommendation, file), recommendations (array of strings), positiveFindings (array of strings). Be specific and concise.';
// EXTENSION POINT: add a new reviewer by appending one entry below.
const reviewers = [
  { reviewerKey: 'architecture', reviewerName: 'Architecture Reviewer', scored: true, focus: 'Clean Architecture, Layering, CQRS, DDD, Vertical Slice, Dependency Injection, Repository Pattern' },
  { reviewerKey: 'solid', reviewerName: 'SOLID Reviewer', scored: true, focus: 'SRP, OCP, LSP, ISP, DIP' },
  { reviewerKey: 'performance', reviewerName: 'Performance Reviewer', scored: true, focus: 'Database queries, LINQ, memory allocations, loops, async, caching, algorithmic complexity' },
  { reviewerKey: 'security', reviewerName: 'Security Reviewer', scored: true, focus: 'OWASP Top 10, authentication, authorization, SQL injection, XSS, secrets, input validation, output encoding, logging sensitive data' },
  { reviewerKey: 'quality', reviewerName: 'Code Quality Reviewer', scored: true, focus: 'Naming, readability, maintainability, magic numbers, duplicate code, large methods, large classes, code smells' },
  { reviewerKey: 'database', reviewerName: 'Database Reviewer', scored: true, focus: 'EF Core, transactions, AsNoTracking, indexes, SaveChanges, N+1 queries, query optimization' },
  { reviewerKey: 'testing', reviewerName: 'Testing Reviewer', scored: true, focus: 'Unit tests, integration tests, coverage estimation, mockability' },
  { reviewerKey: 'api', reviewerName: 'API Reviewer', scored: true, focus: 'REST, DTOs, validation, status codes, pagination, filtering, versioning' },
  { reviewerKey: 'positive', reviewerName: 'Positive Reviewer', scored: false, focus: 'Good practices, reusable code, good architecture, optimizations. Never return only negative feedback.' }
];
return reviewers.map(function (r) {
  const scoreNote = r.scored ? '' : ' Do NOT include a numeric score; set positiveFindings only.';
  const systemPrompt = 'You are the ' + r.reviewerName + ', an expert .NET/C# code reviewer. Focus areas: ' + r.focus + '.' + base + scoreNote;
  return { json: { reviewerKey: r.reviewerKey, reviewerName: r.reviewerName, scored: r.scored, systemPrompt, codeContext, repository, commitSha } };
});

const results = $input.all().map(i => i.json).filter(r => r && r.reviewerKey);
const weights = { architecture: 0.20, security: 0.20, performance: 0.15, quality: 0.15, solid: 0.10, testing: 0.10, database: 0.05, api: 0.05 };
const scores = {};
const seenIssues = {};
const issues = [];
const recsSet = {};
const recommendations = [];
const positiveFindings = [];
for (const r of results) {
  if (r.reviewerKey && typeof r.score === 'number' && weights[r.reviewerKey] !== undefined) { scores[r.reviewerKey] = r.score; }
  const rIssues = Array.isArray(r.issues) ? r.issues : [];
  for (const is of rIssues) {
    const key = ((is.title || '') + '|' + (is.file || '')).toLowerCase().trim();
    if (!seenIssues[key]) { seenIssues[key] = true; issues.push({ title: is.title || '', severity: (is.severity || 'medium'), detail: is.detail || '', recommendation: is.recommendation || '', file: is.file || '', reviewer: r.reviewerKey }); }
  }
  const rRecs = Array.isArray(r.recommendations) ? r.recommendations : [];
  for (const rec of rRecs) { const k = String(rec).toLowerCase().trim(); if (rec && !recsSet[k]) { recsSet[k] = true; recommendations.push(rec); } }
  const rPos = Array.isArray(r.positiveFindings) ? r.positiveFindings : [];
  for (const p of rPos) { if (p) positiveFindings.push(p); }
}
const scoreKeys = ['architecture','solid','security','performance','quality','database','testing','api'];
const finalScores = {};
for (const k of scoreKeys) { finalScores[k] = (typeof scores[k] === 'number') ? scores[k] : null; }
let wsum = 0; let acc = 0;
for (const k of Object.keys(weights)) { if (typeof scores[k] === 'number') { acc += scores[k] * weights[k]; wsum += weights[k]; } }
const overallScore = wsum > 0 ? Math.round(acc / wsum) : null;
const sevRank = { critical: 0, high: 1, medium: 2, low: 3 };
issues.sort((a, b) => (sevRank[(a.severity || 'medium').toLowerCase()] ?? 2) - (sevRank[(b.severity || 'medium').toLowerCase()] ?? 2));
let risk = 'Unknown'; let debt = 'Unknown';
if (overallScore !== null) { if (overallScore >= 85) { risk = 'Low'; debt = 'Low'; } else if (overallScore >= 70) { risk = 'Medium'; debt = 'Medium'; } else { risk = 'High'; debt = 'High'; } }
const nextActions = recommendations.slice(0, 5);
return [{ json: { scores: finalScores, overallScore, risk, technicalDebt: debt, issues, recommendations, positiveFindings, nextActions, reviewerCount: results.length } }];

const agg = $('Aggregate Findings').first().json;
const sum = $input.first().json;
const parsed = (sum && sum.output) ? sum.output : {};
const exec = parsed.executiveSummary || '';
const dev = parsed.developerSummary || '';
const v = $('Validate Input').first().json;
const response = {
  repository: v.repository,
  commit: v.commitSha,
  overallScore: agg.overallScore,
  risk: agg.risk,
  technicalDebt: agg.technicalDebt,
  scores: agg.scores,
  positiveFindings: agg.positiveFindings,
  issues: agg.issues,
  recommendations: agg.recommendations,
  nextActions: agg.nextActions
};
const prNum = (v.pullRequestNumber === null || v.pullRequestNumber === undefined) ? '' : String(v.pullRequestNumber);
const log = {
  organization: v.organization, repository: v.repository, branch: v.branch,
  commit_sha: v.commitSha, pull_request_number: prNum,
  overall_score: (typeof agg.overallScore === 'number') ? agg.overallScore : 0,
  risk: agg.risk || '', summary: exec
};
return [{ json: { response, log, executiveSummary: exec, developerSummary: dev } }];
